# DP: track min cost ending at each color for last house.
# costs[i][c] only adds to choices where last color != c.
def house_paint(costs):
    if not costs:
        return 0
    r, g, b = 0, 0, 0  # running mins for the 3 colors
    for cr, cg, cb in costs:
        r, g, b = cr + min(g, b), cg + min(r, b), cb + min(r, g)
