# DP in place: dp[i][j] = grid[i][j] + min(dp[i-1][j], dp[i][j-1])
def min_path_sum(grid):
    m, n = len(grid), len(grid[0])
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue  # start cell unchanged
            up = grid[i-1][j] if i else float('inf')
            left = grid[i][j-1] if j else float('inf')
            grid[i][j] += min(up, left)
    return grid[-1][-1]
```

