# DP: dp[i] True iff s[:i] is segmentable. Check all splits.
def word_break(s, words):
    wset = set(words)
    dp = [False] * (len(s) + 1)
    dp[0] = True  # empty prefix is segmentable
    for i in range(1, len(s) + 1):
        for j in range(i):
            if dp[j] and s[j:i] in wset:
                dp[i] = True
                break  # one valid split is enough
    return dp[-1]
