# Subset-sum DP: can we reach target = total/2?
def partition_equal(nums):
    total = sum(nums)
    if total % 2:
        return False  # odd total can't split evenly
    target = total // 2
    reachable = {0}
    for n in nums:
        reachable |= {r + n for r in reachable if r + n <= target}
    return target in reachable
