# DP on (i,j): if s[i]==s[j], dp[i][j]=dp[i+1][j-1]+2 else max of dropping one end.
def longest_palindrome_sub(s):
    n = len(s)
    dp = [[0]*n for _ in range(n)]
    for i in range(n-1, -1, -1):
        dp[i][i] = 1  # single char is length-1 palindrome
        for j in range(i+1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])
    return dp[0][n-1]
```

