# DP bottom-up: dp[i] = 1 + min of valid predecessors.
def min_steps_to_one(n):
    dp = [0] * (n + 1)
    for i in range(2, n + 1):
        best = dp[i-1]  # always can subtract 1
        if i % 2 == 0:
            best = min(best, dp[i//2])
        if i % 3 == 0:
            best = min(best, dp[i//3])
        dp[i] = best + 1
    return dp[n]
```

