# Order matters: dp[i] = sum of dp[i-s] for each step s. Like staircase variants.
def count_ways_to_sum(n, steps):
    dp = [0] * (n + 1)
    dp[0] = 1  # one way to make 0: empty sequence
    for i in range(1, n + 1):
        for s in steps:
            if i - s >= 0:
                dp[i] += dp[i - s]
    return dp[n]
