# Topo sort (Kahn): cycle iff not all nodes processed.
from collections import defaultdict, deque
def can_finish(n, prereqs):
    g = defaultdict(list); ind = [0]*n
    for a,b in prereqs:
        g[b].append(a); ind[a] += 1
    q = deque(i for i in range(n) if not ind[i])
    done = 0
    while q:
        u = q.popleft(); done += 1
        for v in g[u]:
            ind[v] -= 1
            if not ind[v]: q.append(v)
    return done == n
```

