from collections import deque
def word_ladder(a, z, ws):
    W = set(ws)
    if z not in W: return 0
    q = deque([(a,1)]); S = {a}
    while q:
        w,d = q.popleft()
        if w == z: return d
        for i in range(len(w)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                x = w[:i]+c+w[i+1:]
                if x in W and x not in S:
                    S.add(x); q.append((x,d+1))
