# Backtrack across digits; each digit multiplies choices.
def letter_combos(digits):
    if not digits: return []
    m = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}
    out = []
    def bt(i, path):
        if i == len(digits):
            out.append(''.join(path)); return
        for ch in m[digits[i]]:
            path.append(ch); bt(i+1, path); path.pop()
    bt(0, []); return out
