def generate_parens(n):
    out = []
    def bt(s, o, c):
        if len(s) == 2*n:
            out.append(s); return
        if o < n:
            bt(s + '(', o + 1, c)
        if c < o:  # keep prefix valid
            bt(s + ')', o, c + 1)
