# Backtrack: pick 1-3 chars per segment, 4 segments total.
def restore_ips(s):
    out = []
    def bt(i, parts):
        if len(parts) == 4:
            if i == len(s): out.append('.'.join(parts))
            return
        for L in (1,2,3):
            seg = s[i:i+L]
            if not seg: return
            if (seg[0]=='0' and L>1) or int(seg)>255: continue
            bt(i+L, parts+[seg])
    bt(0, []); return out
