# Binary search: move toward the higher neighbor; a peak must exist there.
def find_peak(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < nums[mid + 1]:
            lo = mid + 1  # ascending: peak is to the right
        else:
            hi = mid  # descending or equal: peak here or left
    return lo
