# Stack: push operands; on operator pop two, push result. Watch int division.
def eval_rpn(tokens):
    stack = []
    for t in tokens:
        if t in '+-*/':
            b = stack.pop(); a = stack.pop()
            if t == '+': stack.append(a + b)
            elif t == '-': stack.append(a - b)
            elif t == '*': stack.append(a * b)
            else: stack.append(int(a / b))  # truncate toward zero
        else:
            stack.append(int(t))
    return stack[0]
```

