# Stack of (prev_string, repeat); flush on ']'.
def decode_string(s):
    stack, cur, k = [], '', 0
    for ch in s:
        if ch.isdigit():
            k = k * 10 + int(ch)  # build multi-digit count
        elif ch == '[':
            stack.append((cur, k)); cur, k = '', 0
        elif ch == ']':
            prev, rep = stack.pop()
            cur = prev + cur * rep
        else:
            cur += ch
    return cur
```

