# Expand-around-center; try both odd and even centers.
def longest_palindrome_sub_str(s):
    if not s: return ''
    start = end = 0
    def grow(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1; r += 1
        return l + 1, r - 1
    for i in range(len(s)):
        for l, r in (grow(i, i), grow(i, i + 1)):
            if r - l > end - start:
                start, end = l, r
    return s[start:end + 1]
```

