# If total gas < total cost, impossible. Else greedy: reset start on deficit.
def gas_station(gas, cost):
    if sum(gas) < sum(cost):
        return -1  # infeasible globally
    start = tank = 0
    for i in range(len(gas)):
        tank += gas[i] - cost[i]
        if tank < 0:
            start = i + 1; tank = 0  # cannot reach i+1 from any earlier start
    return start
