# Greedy: extend window to last index of any seen char; cut when reached.
def partition_labels(s):
    last = {ch: i for i, ch in enumerate(s)}
    out, start, end = [], 0, 0
    for i, ch in enumerate(s):
        end = max(end, last[ch])  # window must include all of ch
        if i == end:
            out.append(end - start + 1)
            start = i + 1
    return out
