# Floyd: fast/slow meet inside loop; reset one to head, step together.
def detect_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next; fast = fast.next.next
        if slow is fast:
            slow = head  # phase 2: equal distance to loop start
            while slow is not fast:
                slow = slow.next; fast = fast.next
            return slow
    return None
```

