# Min-heap of (val, idx, node); idx breaks ties since nodes aren't comparable.
import heapq
def merge_k_lists(lists):
    h = []
    for i, node in enumerate(lists):
        if node: heapq.heappush(h, (node.val, i, node))
    dummy = type(lists[0])(0) if lists and lists[0] else None
    tail = dummy
    while h:
        v, i, n = heapq.heappop(h)
        tail.next = n; tail = n
        if n.next: heapq.heappush(h, (n.next.val, i, n.next))
    return dummy.next if dummy else None
